const body = $input.item.json.body || $input.item.json;
const text = body.text || '';

let normalizedText = text.replace(/(\d)\.(\d{3})/g, '$1$2');
normalizedText = normalizedText.replace(/(\d),(\d)/g, '$1.$2');

const regex = /-?\d+(\.\d+)?([eE][-+]?\d+)?/g;
const matches = normalizedText.match(regex);

if (!matches || matches.length === 0) {
  return [{ json: { error: 'No se detectaron números válidos.' } }];
}

// IMPORTANTE: Devolvemos un solo objeto con arrays para evitar que n8n ejecute los siguientes nodos N veces por separado
const numbers = matches.map(Number);

return {
  json: {
    todos: numbers,
    positivos: numbers.filter(n => n >= 0),
    negativos: numbers.filter(n => n < 0)
  }
};

const data = $input.item.json;

if (data.error) return { json: data };

const positivos = data.positivos || [];
const negativos = data.negativos || [];
const todos = data.todos || [];

// Cálculos
const cantidad = todos.length;
const suma = todos.reduce((a, b) => a + b, 0);
const promedio = cantidad > 0 ? suma / cantidad : 0;

// Mediana
const sorted = [...todos].sort((a, b) => a - b);
const mid = Math.floor(cantidad / 2);
const mediana = cantidad % 2 !== 0 ? sorted[mid] : (sorted[mid - 1] + sorted[mid]) / 2;

// Desviación
const varianza = todos.reduce((a, b) => a + Math.pow(b - promedio, 2), 0) / cantidad;
const desviacion = Math.sqrt(varianza);

// Frecuencias
const frecuencias = {};
todos.forEach(n => frecuencias[n] = (frecuencias[n] || 0) + 1);

const maxFreq = Math.max(...Object.values(frecuencias));
const moda = Object.keys(frecuencias).filter(k => frecuencias[k] === maxFreq).map(Number);

// Primos
const isPrime = num => {
    if (num <= 1 || !Number.isInteger(num)) return false;
    for (let i = 2; i <= Math.sqrt(num); i++) if (num % i === 0) return false;
    return true;
};

return {
  json: {
    cantidad,
    suma: Number(suma.toFixed(2)),
    promedio: Number(promedio.toFixed(2)),
    mediana: Number(mediana.toFixed(2)),
    desviacion: Number(desviacion.toFixed(2)),
    moda: maxFreq === 1 ? [] : moda,
    minimo: sorted.length ? sorted[0] : 0,
    maximo: sorted.length ? sorted[sorted.length - 1] : 0,
    lista_desc: [...sorted].reverse(),
    lista_asc: sorted,
    positivos: positivos.sort((a,b) => b-a),
    negativos: negativos.sort((a,b) => a-b),
    pares: todos.filter(n => Number.isInteger(n) && n % 2 === 0).sort((a,b)=>a-b),
    impares: todos.filter(n => Number.isInteger(n) && n % 2 !== 0).sort((a,b)=>a-b),
    primos: todos.filter(isPrime).sort((a,b)=>a-b),
    frecuencias
  }
};
